CREATE TABLE ibexa_search_object_word_link (id SERIAL NOT NULL, content_type_field_definition_id INT DEFAULT 0 NOT NULL, content_type_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT 0 NOT NULL, frequency DOUBLE PRECISION DEFAULT '0' NOT NULL, identifier VARCHAR(255) DEFAULT '' NOT NULL, integer_value INT DEFAULT 0 NOT NULL, next_word_id INT DEFAULT 0 NOT NULL, placement INT DEFAULT 0 NOT NULL, prev_word_id INT DEFAULT 0 NOT NULL, published INT DEFAULT 0 NOT NULL, section_id INT DEFAULT 0 NOT NULL, word_id INT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, PRIMARY KEY(id));
